const D = { energy: .6, scale: 1, density: .5, speed: 1, sweep: .5, hue: 210, x: .5, y: .66, style: 'steel', seed: 0, alpha: 100 };
const P = Object.assign({}, D, (window.state.P && window.state.P.__SLOT__) || {});
const S = window.state.__SLOT__ || (window.state.__SLOT__ = {});
const K = window.state.clk || { t:0, cps:.5, beat:0, bar:0, cyc:0, phase:0, pulse:0, swell:0, section:0, intensity:.6, fps:60 };
const A = window.state.audio || { bass:0, lowmid:0, mid:0, treble:0, rms:0, fft:[] };

// ---- An array of parabolic dish antennas on a ridge, slowly slewing to track across the
// sky, an unseen light raking the panelled reflectors. A SET: dishes stand along a lower
// band and leave the sky open; alpha scales every mark. Not a crane/pylon/lighthouse. ----

const cl = (v,a,b) => v<a?a:(v>b?b:v);
const u = Math.min(width, height), sd = P.seed|0;
const fr = i => { const s = Math.sin(i*127.1 + sd*311.7)*43758.5453; return s - Math.floor(s); };
const sty = P.style, en = cl(P.energy,0,1), dn = cl(P.density,0,1), swp = cl(P.sweep,0,1);
const HU = ((P.hue%360)+360)%360, tt = K.t;
const bp = sty==='blueprint', dusk = sty==='dusk', therm = sty==='thermal', eng = sty==='engraving';
const AL = cl(P.alpha,0,100);
if (AL > 0.5) {

const bass = (S.b = (S.b||0)*.84 + (A.bass||0)*.16);
const light = (.5+.5*en)*(.55+.5*K.intensity) + bass*.2;
// an unseen sun/beacon whose direction drifts -> a raking highlight travels the metal
const sunA = tt*.06*swp + .6*Math.sin(tt*.11+1.0);
const sunV = [Math.cos(sunA-1.2), Math.sin(sunA-1.2)];

// colour ramp helper for the metal
function metal(v){                                        // v: 0 shadow .. 1 hot highlight
  if (bp)   return [196, 60, cl(14+v*10,8,30)];
  if (eng)  return [34, 5, cl(10+v*84,6,96)];
  if (therm)return [cl(250-v*250,0,300), 80, cl(24+v*70,8,98)];
  if (dusk) return [cl(HU+18-v*30,0,360), cl(40-v*24,4,60), cl(8+v*74,5,86)];
  return [cl(HU-4+v*8,0,360), cl(16-v*10,2,26), cl(20+v*62,6,92)];    // cool brushed steel
}
function setF(c,a){ fill(c[0],c[1],c[2],a*AL/100); }
function setS(c,a){ stroke(c[0],c[1],c[2],a*AL/100); }

const ridgeY = cl(P.y,.35,.85)*height;
const baseS = u*.16*cl(P.scale,.3,2.4);
const nD = 3 + Math.round(dn*3);

for (let i=0; i<nD; i++){
  const depth = fr(i*5.7);                                // 0 far .. 1 near
  const dishS = baseS*(0.45 + depth*0.85);
  const jitterX = (fr(i*3.1)-.5);
  const dx = cl(P.x,.05,.95)*width + (i-(nD-1)/2)*width*0.19 + jitterX*width*0.05;
  const dy = ridgeY - dishS*0.15 + (1-depth)*u*0.05;      // far dishes sit a touch higher/back
  const dim = 0.55 + depth*0.45;                          // atmospheric fade for far dishes
  const ph = fr(i*7.7)*6.28;
  // slew: azimuth swings the dish, elevation nods it (incommensurate real-time drift) — kept
  // brisk enough that the whole array visibly turns over an 8s window
  const az = 0.62*Math.sin(tt*(.11+.03*i)*P.speed + ph) + 0.26*Math.sin(tt*.23*P.speed+ph*1.7);
  const el = 0.55 + 0.32*Math.sin(tt*(.08+.025*i)*P.speed + ph*1.3) + 0.14*Math.sin(tt*.17*P.speed);
  push();
  translate(dx, dy);
  // ---- pedestal / alt-az mount on the ridge ----
  const pedH = dishS*0.9;
  setF(metal(.30*light+.1), 88*dim);
  noStroke();
  quad(-dishS*.16, 0, dishS*.16, 0, dishS*.10, -pedH, -dishS*.10, -pedH);    // tapered column
  setF(metal(.5*light+.15), 90*dim);
  rect(-dishS*.16, -pedH-dishS*.10, dishS*.32, dishS*.14, dishS*.03);        // yoke/turret
  // ---- the dish assembly, rotated by azimuth about the pivot ----
  translate(0, -pedH-dishS*.05);
  rotate(az*0.7);
  // reflector rim: an ellipse foreshortened by elevation
  const Dw = dishS*1.5;
  const Dh = Dw*(0.30 + 0.55*cl(el,0,1));                 // nods -> minor axis changes
  const cyO = -Dh*0.55;                                   // dish centre above pivot
  // concave face: nested ellipses, brighter where the paraboloid faces the sun
  const faceUp = [Math.sin(az*0.7), -Math.cos(az*0.7)*el - (1-el)*0.4];
  const facing = cl(faceUp[0]*sunV[0] + faceUp[1]*sunV[1], -1, 1);
  const faceLum = cl(0.42 + facing*0.5, 0.1, 1)*light;
  for (let r=6;r>=0;r--){
    const rr = r/6;
    const cc = metal(cl(faceLum*(0.5+0.5*rr) - (1-rr)*0.15, 0, 1));
    setF(cc, (dusk? 78: 88)*dim);
    if (bp || eng){ noFill(); setS(metal(cl(faceLum,0,1)), 60*dim); strokeWeight(Math.max(1,u*.0011)); }
    else noStroke();
    ellipse(0, cyO, Dw*rr, Dh*rr);
  }
  // panel structure: concentric arcs + radial ribs (texture over flat fill)
  noFill(); setS(metal(cl(faceLum*.5,0,1)), 42*dim); strokeWeight(Math.max(1,u*.0009));
  for (let rr=0.35;rr<1.0;rr+=0.22) ellipse(0,cyO,Dw*rr,Dh*rr);
  for (let a=0;a<12;a++){ const an=a/12*6.283; line(0,cyO, Math.cos(an)*Dw*.5, cyO+Math.sin(an)*Dh*.5); }
  // rim edge highlight
  noFill(); setS(metal(cl(0.6+faceLum*.5,0,1)), 70*dim); strokeWeight(Math.max(1,u*.0016));
  ellipse(0,cyO,Dw,Dh);
  // ---- feed support: a quadripod converging to a feed cabin at the focus ----
  const foX = faceUp[0]*Dh*1.15, foY = cyO + faceUp[1]*Dh*1.15;
  setS(metal(.4*light+.1), 66*dim); strokeWeight(Math.max(1,u*.0011));
  for (let leg=0; leg<4; leg++){ const an=(leg/4)*6.283+.6;
    line(Math.cos(an)*Dw*.42, cyO+Math.sin(an)*Dh*.42, foX, foY); }
  setF(metal(.55*light+.2), 88*dim); noStroke();
  ellipse(foX, foY, dishS*.16, dishS*.16);
  // counterweight arm behind
  setS(metal(.35*light+.05), 60*dim); strokeWeight(Math.max(1,u*.0016));
  line(0,cyO, -faceUp[0]*Dh*.5, cyO-faceUp[1]*Dh*.5);
  pop();
}
blendMode(BLEND); noTint(); drawingContext.shadowBlur=0; strokeWeight(1);
}
